inline const BakedBlockModel *FindBlock(const std::string &name) {
  int lo = 0;
  int hi = 652 - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    int cmp = std::strcmp(name.c_str(), kBlocks[mid].name);
    if (cmp == 0) return &kBlocks[mid];
    if (cmp < 0) hi = mid - 1;
    else lo = mid + 1;
  }
  return nullptr;
}

inline const BakedBlockModel *FindVariant(const std::string &name) {
  int lo = 0;
  int hi = 842 - 1;
  while (lo <= hi) {
    int mid = (lo + hi) / 2;
    int cmp = std::strcmp(name.c_str(), kVariantModels[mid].name);
    if (cmp == 0) return &kVariantModels[mid];
    if (cmp < 0) hi = mid - 1;
    else lo = mid + 1;
  }
  return nullptr;
}

